//! 🧪️ Original Window genesis agrees with independent canonical and digest oracles and closes every actual allocation.
use super::*;
use semio_framework_job::*;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
use semio_framework_dsl_record::{BorrowedDslRecord,native_encoding::FieldProjectionSource};
#[path="🧸️fixture/🦀️.rs"]
mod fixture;
pub(crate) use fixture::{Owner,State,Mutation};
fn fixture()->serde_json::Value{serde_json::from_str(include_str!("🔣️.json")).unwrap()}
pub(crate) fn grant()->RetainedCloneGrant{let law=fixture();let g=&law["grant"];RetainedCloneGrant{maximum_items:g["items"].as_u64().unwrap()as usize,maximum_copy_bytes:g["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["depth"].as_u64().unwrap()as usize}}
fn caller()->OriginalJobFixtureCaller{OriginalJobFixtureCaller::admit(OperationId(3301),Generation(19),RetainedCloneGrant{maximum_items:1<<30,maximum_copy_bytes:1<<29,maximum_capacity_bytes:1<<26,maximum_release_bytes:1<<26,maximum_depth:4096},default_now_us,u64::MAX,1<<28)}
fn turn<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,grant:RetainedCloneGrant,run:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{let(result,heap)=observe(||caller.turn_with_decoder(grant,decoder,run));let p=caller.receipt();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes),"original physical receipt differs: {p:?}");result.unwrap()}
fn drain(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,birth:&mut Option<Box<WindowConfigPartitionBirth<Owner>>>){for _ in 0..200000{let Some(owner)=birth.as_mut()else{return};if owner.terminal_is_empty(){turn(caller,decoder,grant(),|cx|{close_original_retained_step(cx,WindowConfigPartitionBirth::<Owner>::boxed_release_demands(),|_|{*birth=None;Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:WindowConfigPartitionBirth::<Owner>::boxed_release_demands().copy_bytes,released_bytes:WindowConfigPartitionBirth::<Owner>::boxed_release_demands().release_bytes,..Default::default()}))})?;Ok(())});return}turn(caller,decoder,grant(),|cx|cx.with_original_retirement(|cx|{owner.close_step(cx)?;Ok(())}));}panic!("original Window genesis did not close")}
fn finish(mut caller:OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){while !decoder.terminal_is_empty(){caller.turn(grant(),|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}caller.retire(grant());}
#[test]
fn original_window_genesis_denied_birth_allocates_nothing(){let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let actor=protocol::ActorId("window-reader".into());for axis in 0..4{let mut denied=grant();match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=0,2=>denied.maximum_capacity_bytes=0,_=>denied.maximum_depth=0}let result=turn(&mut caller,&mut decoder,denied,|cx|WindowConfigPartitionBirth::<Owner>::admit("camera-left",&actor,cx));assert!(result.is_none());}finish(caller,&mut decoder);}
#[test]
fn original_window_genesis_native_store_matches_canonical_pack_and_independent_digest(){let law=fixture();let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let actor=protocol::ActorId(law["actor"].as_str().unwrap().into());let mut birth=turn(&mut caller,&mut decoder,grant(),|cx|WindowConfigPartitionBirth::<Owner>::admit(law["window"].as_str().unwrap(),&actor,cx));let mut candidate=None;for index in 0..law["maximumTurns"].as_u64().unwrap(){candidate=turn(&mut caller,&mut decoder,grant(),|cx|birth.as_mut().unwrap().step(cx));if candidate.is_some(){break}assert!(index+1<law["maximumTurns"].as_u64().unwrap(),"Window genesis stalled: {:?} caller={:?} fuel={}",birth.as_ref().unwrap().progress(),caller.remaining_grant(),caller.fuel_remaining());}let(window,mut store)=candidate.unwrap();assert_eq!(window,law["window"].as_str().unwrap());let state=State::default();assert_eq!(store.snapshot().unwrap(),state);assert_eq!(state.zoom,law["state"]["zoom"].as_f64().unwrap());let canonical=<State as pack::snapshot::ArtifactPack>::encode_pack_with(&state,&Default::default()).unwrap();assert_eq!(store.envelope().vcs.genesis.pack(),canonical.as_slice());assert_eq!(store.envelope().vcs.genesis.facts().digest(),*blake3::hash(&canonical).as_bytes());assert_eq!(store.snapshot_read_leases_terminal_is_empty(),law["registryEmptyBeforeCustodyClose"].as_bool().unwrap());assert!(!store.owners.snapshot_read_leases.closed());let mut idle=0;for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}let before=caller.cumulative_receipt();turn(&mut caller,&mut decoder,grant(),|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));let after=caller.cumulative_receipt();if after==before{idle+=1}else{idle=0}assert!(idle<1024,"[DEBUG] native Store close made no original progress: next={:?} total={after:?} disposer={:?} registry_closed={} returned_empty={} displaced_empty={} dag_empty={} histories={:?} registry={:?} queues={:?}",store.close_owned_demands(4096),store.owners.owned_disposer.as_ref().map(|owner|(owner.terminal_is_empty(store.as_ref()),owner.demands(store.as_ref(),4096))),store.owners.snapshot_read_leases.closed(),store.snapshot_read_leases_terminal_is_empty(),store.maintenance_retirements_terminal_is_empty(),store.log.dag.backing_is_empty(),[store.log.applied_edit_ids.capacity(),store.log.redo_edit_ids.capacity(),store.cursor.revision_accumulator.applied.capacity(),store.cursor.revision_accumulator.redo.capacity()],store.owners.snapshot_read_leases.empty_backing_demands(),[store.owners.displaced_retirements.owners.capacity(),store.live.prefix_ring.capacity(),store.wire.member_inbox.capacity()]);assert!(index<1048575,"[DEBUG] native Store close horizon: next={:?} total={after:?}",store.close_owned_demands(4096));}drain(&mut caller,&mut decoder,&mut birth);finish(caller,&mut decoder);}
#[test]
fn original_window_genesis_cancellation_closes_actual_prefixes(){let law=fixture();for cut in law["cancelAt"].as_array().unwrap(){let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let actor=protocol::ActorId(law["actor"].as_str().unwrap().into());let mut birth=turn(&mut caller,&mut decoder,grant(),|cx|WindowConfigPartitionBirth::<Owner>::admit(law["window"].as_str().unwrap(),&actor,cx));for _ in 0..cut.as_u64().unwrap(){assert!(turn(&mut caller,&mut decoder,grant(),|cx|birth.as_mut().unwrap().step(cx)).is_none());}birth.as_mut().unwrap().begin_close();drain(&mut caller,&mut decoder,&mut birth);finish(caller,&mut decoder);}}
